# --- HELPER UTILITIES ---
def _args(update: Update) -> str:
    if update.message and update.message.text:
        parts = update.message.text.split(maxsplit=1)
        if len(parts) > 1:
            return parts[1].strip()
    return ""

def trunc_title(title: str) -> str:
    return title[:128]

async def set_prefix_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    global current_prefix
    if update.effective_user.id not in (sudo_users | {OWNER_ID}):
        return
    if not context.args:
        return await update.message.reply_text(f"⚠️ *Pardon, sweetie:* Please specify a new prefix, honey! Current prefix: `{current_prefix}` 🌸", parse_mode="Markdown")
    
    new_pfx = context.args[0].strip()
    current_prefix = new_pfx
    
    # Automatically update prefix for all CommandHandlers dynamically
    for group in context.application.handlers.values():
        for handler in group:
            if isinstance(handler, CommandHandler):
                handler.command_prefix = current_prefix
                
    await report(update, "𝑷𝑹𝑬𝑭𝑰𝑿 𝑼𝑷𝑫𝑨𝑻𝑬𝑫", f"Command prefix successfully modified to `{current_prefix}` for us, darling! ✨", "SUCCESS")


async def stop_nc_engine(update: Update, context: ContextTypes.DEFAULT_TYPE, task_key: str, title: str):
    if update.effective_user.id not in (sudo_users | {OWNER_ID}):
        return
    cid = update.effective_chat.id
    if cid in active_tasks:
        active_tasks[cid][task_key] = False
    await report(update, title, f"{title} stream successfully terminated, darling. ✨", "SUCCESS")

async def stop_task_engine(update: Update, context: ContextTypes.DEFAULT_TYPE, task_key: str, title: str):
    if update.effective_user.id not in (sudo_users | {OWNER_ID}):
        return
    cid = update.effective_chat.id
    if cid in active_tasks:
        active_tasks[cid][task_key] = False
    await report(update, title, f"{title} execution successfully halted, darling. ✨", "SUCCESS")

async def generic_nc_handler(update: Update, context: ContextTypes.DEFAULT_TYPE, templates: list, task_key: str, title: str):
    global current_prefix
    if update.effective_user.id not in (sudo_users | {OWNER_ID}):
        return
    target = _args(update)
    if not target:
        return await update.message.reply_text(f"💅🏻 *Pardon:* Kindly specify a target name, honey. `{current_prefix}{task_key} <name>` ✨", parse_mode="Markdown")
    cid = update.effective_chat.id
    if cid not in active_tasks:
        active_tasks[cid] = {}
    active_tasks[cid][task_key] = True
    await report(update, title, f"Assault active on target: `{target}` 🔥", "SUCCESS")
    while active_tasks[cid].get(task_key, False):
        try:
            tpl = random.choice(templates)
            msg_text = tpl.format(target=target)
            tasks = [context.bot.send_message(cid, msg_text)]
            for bot_data in active_sub_bots.values():
                tasks.append(bot_data["app"].bot.send_message(cid, msg_text))
            await asyncio.gather(*tasks, return_exceptions=True)
            await asyncio.sleep(0.1)
        except:
            break

async def run_nc2_engine(update: Update, context: ContextTypes.DEFAULT_TYPE, task_key: str, templates: list, emojis: list, title: str):
    global current_prefix
    if update.effective_user.id not in (sudo_users | {OWNER_ID}):
        return
    name = _args(update)
    if not name:
        return await update.message.reply_text(f"💅🏻 *Pardon:* Kindly specify a name, honey. `{current_prefix}{task_key} <name>` ✨", parse_mode="Markdown")
    cid = update.effective_chat.id
    if cid not in active_tasks:
        active_tasks[cid] = {}
    active_tasks[cid][task_key] = True
    await report(update, title, f"Hyper-assault active on: `{name}` 🧨", "SUCCESS")
    while active_tasks[cid].get(task_key, False):
        try:
            tpl = random.choice(templates)
            emo = random.choice(emojis)
            msg_text = tpl.format(name=name, emo=emo)
            tasks = [context.bot.send_message(cid, msg_text)]
            for bot_data in active_sub_bots.values():
                tasks.append(bot_data["app"].bot.send_message(cid, msg_text))
            await asyncio.gather(*tasks, return_exceptions=True)
            await asyncio.sleep(0.1)
        except:
            break

