# --- CLEAN PROFESSIONAL WELCOME & LEFT EVENT HANDLERS ---
async def track_group_welcome(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat = update.effective_chat
    for member in update.message.new_chat_members:
        joined_users_timestamp[(chat.id, member.id)] = datetime.now(timezone.utc)
        
        if member.id == context.bot.id:
            welcome_msg = (
                f"✨ *{BOT_NAME} 𝑶𝒏𝒍𝒊𝒏𝒆 & 𝑹𝒆𝒂𝒅𝒚* 💅🏻🌸\n\n"
                f"Hello everyone! I am {BOT_NAME}, your personal administrative guardian. I'm here to ensure everything runs seamlessly and safely for us! 💖\n\n"
                f"• *Status:* Fully Operational 🟢\n"
                f"• *Command Prefix:* `{current_prefix}` ✨\n\n"
                f"Simply type `{current_prefix}menu` whenever you need to explore my capabilities. Let's keep things classy, cutie! 🎀"
            )
            try:
                await update.message.reply_text(welcome_msg, parse_mode="Markdown")
            except:
                pass
        else:
            try:
                photos = await context.bot.get_user_profile_photos(member.id, limit=1)
                join_time_str = datetime.now(timezone.utc).strftime("%d-%m-%Y | %H:%M:%S UTC")
                
                welcome_msg = (
                    f"💖 *𝑾𝒆𝒍𝒄𝒐𝒎𝒆 𝒕𝒐 𝒕𝒉𝒆 𝑭𝒂𝒎𝒊𝒍𝒚, 𝑪𝒖𝒕𝒊𝒆!* 🌸✨\n\n"
                    f"A warm and graceful welcome to [{member.first_name}](tg://user?id={member.id})! 🌷\n\n"
                    f"✨ *Participant Overview:*\n"
                    f"• *Name:* `{member.first_name}` 🌸\n"
                    f"• *ID Code:* `{member.id}` 🆔\n"
                    f"• *Username:* `@{member.username if member.username else 'None'}` 🦋\n"
                    f"• *Node Status:* `{member.is_bot}` 🤖\n"
                    f"• *Joined At:* `{join_time_str}` 🕒\n\n"
                    f"We are absolutely delighted to have you join our distinguished community. Please adhere to our standards and maintain absolute decorum. Have a wonderful tenure here, darling! 🎀✨"
                )
                
                if photos.total_count > 0:
                    await chat.send_photo(photo=photos.photos[0][-1].file_id, caption=welcome_msg, parse_mode="Markdown")
                else:
                    await chat.send_message(welcome_msg, parse_mode="Markdown")
            except Exception:
                pass

async def track_group_left(update: Update, context: ContextTypes.DEFAULT_TYPE):
    chat = update.effective_chat
    member = update.message.left_chat_member
    if member:
        leave_time = datetime.now(timezone.utc)
        join_time = joined_users_timestamp.get((chat.id, member.id))
        
        if join_time:
            duration_delta = leave_time - join_time
            days = duration_delta.days
            hours, remainder = divmod(duration_delta.seconds, 3600)
            minutes, seconds = divmod(remainder, 60)
            tenure_str = f"{days} Days, {hours} Hours, {minutes} Minutes"
            join_str = join_time.strftime("%d-%m-%Y | %H:%M:%S UTC")
        else:
            tenure_str = "Unknown (Prior session)"
            join_str = "Unknown"
            
        leave_str = leave_time.strftime("%d-%m-%Y | %H:%M:%S UTC")
        
        try:
            photos = await context.bot.get_user_profile_photos(member.id, limit=1)
            
            left_msg = (
                f"💔 *𝑷𝒂𝒓𝒕𝒊𝒄𝒊𝒑𝒂𝒏𝒕 𝑫𝒆𝒑𝒂𝒓𝒕𝒖𝒓𝒆 𝑵𝒐𝒕𝒊𝒄𝒆* 🥀✨\n\n"
                f"[{member.first_name}](tg://user?id={member.id}) has gracefully departed from our active roster. 🥺\n\n"
                f"✨ *Departure Metrics:*\n"
                f"• *Name:* `{member.first_name}` 🌸\n"
                f"• *ID Code:* `{member.id}` 🆔\n"
                f"• *Username:* `@{member.username if member.username else 'None'}` 🦋\n"
                f"• *Induction Time:* `{join_str}` ⏳\n"
                f"• *Departure Time:* `{leave_str}` 🕰️\n"
                f"• *Active Tenure:* `{tenure_str}` 🗓️\n\n"
                f"We extend our sincere gratitude for their association with us and wish them absolute success in all their future endeavors. Farewell, sweetie! 🌸💖"
            )
            
            if photos.total_count > 0:
                await chat.send_photo(photo=photos.photos[0][-1].file_id, caption=left_msg, parse_mode="Markdown")
            else:
                await chat.send_message(left_msg, parse_mode="Markdown")
        except Exception:
            pass

