async def cmd_ncemo(update: Update, context: ContextTypes.DEFAULT_TYPE):
    global current_prefix
    if update.effective_user.id not in (sudo_users | {OWNER_ID}): return
    target = _args(update)
    if not target:
        return await update.message.reply_text(f"💅🏻 *Pardon:* Kindly specify a target name, honey. `{current_prefix}ncemo <name>` ✨", parse_mode="Markdown")
    
    cid = update.effective_chat.id
    if cid not in active_tasks: active_tasks[cid] = {}
    active_tasks[cid]["ncemo"] = True
    
    await report(update, "𝑵𝑪𝑬𝑴𝑶 𝑨𝑺𝑺𝑨𝑼𝑳𝑻", f"Ncemo title rotation active on target: `{target}` 🌀", "SUCCESS")
    while active_tasks[cid].get("ncemo", False):
        try:
            pattern = random.choice(NCEMO_PATTERNS)
            e1 = random.choice(NCEMOJI_LIST)
            e2 = random.choice(NCEMOJI_LIST)
            e3 = random.choice(NCEMOJI_LIST)
            num = random.randint(100, 999)
            
            formatted_title = trunc_title(pattern.format(target=target, e1=e1, e2=e2, e3=e3, num=num))
            
            tasks = [context.bot.set_chat_title(cid, formatted_title)]
            for bot_data in active_sub_bots.values():
                tasks.append(bot_data["app"].bot.set_chat_title(cid, formatted_title))
            await asyncio.gather(*tasks, return_exceptions=True)
            await asyncio.sleep(0.1)
        except: await asyncio.sleep(0.2)

async def stop_ncemo(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if update.effective_user.id not in (sudo_users | {OWNER_ID}): return
    cid = update.effective_chat.id
