async def cmd_rr(update: Update, context: ContextTypes.DEFAULT_TYPE):
    global current_prefix
    if update.effective_user.id not in (sudo_users | {OWNER_ID}): return
    if not update.message.reply_to_message:
        return await update.message.reply_text(f"💅🏻 *Pardon:* Reply to a target message and use `{current_prefix}rr <text>`, darling. 💬🌸", parse_mode="Markdown")
    if not context.args:
        return await update.message.reply_text(f"❗ *Syntax Error:* `{current_prefix}rr <text>` is required. ✨", parse_mode="Markdown")
    
    chat_id = update.effective_chat.id
    target_msg_id = update.message.reply_to_message.message_id
    text = " ".join(context.args)
    
    if chat_id not in active_tasks: active_tasks[chat_id] = {}
    active_tasks[chat_id]["rr"] = True
    reply_raid_data[chat_id] = {"message_id": target_msg_id, "text": text}
    
    await report(update, "𝑹𝑬𝑷𝑳𝒀 𝑹𝑨𝑰𝑫 𝑨𝑪𝑻𝑰𝑽𝑬", f"Target message locked for endless battalion replies:\n• Text: `{text}` 💬", "SUCCESS")
    while active_tasks[chat_id].get("rr", False):
        try:
            tasks = [context.bot.send_message(chat_id=chat_id, text=text, reply_to_message_id=target_msg_id)]
            for bot_data in active_sub_bots.values():
                tasks.append(bot_data["app"].bot.send_message(chat_id=chat_id, text=text, reply_to_message_id=target_msg_id))
            await asyncio.gather(*tasks, return_exceptions=True)
            await asyncio.sleep(0.08)
        except: break

