    active_tasks[cid][task_key] = True
    await report(update, module_title, "Tactical deployment stream active, darling. ⚡", "SUCCESS")
    while active_tasks[cid].get(task_key, False):
        try:
            chosen = random.choice(templates)
            tasks = [context.bot.send_message(cid, chosen)]
            for bot_data in active_sub_bots.values():
                tasks.append(bot_data["app"].bot.send_message(cid, chosen))
            await asyncio.gather(*tasks, return_exceptions=True)
            await asyncio.sleep(0.1)
        except: break

