# --- MULTI-BOT WORKER & CONTROL HUB ---
async def add_bot_worker(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if update.effective_user.id not in (sudo_users | {OWNER_ID}): return
    if not context.args: return
    sub_token = context.args[0].strip()
    if sub_token in active_sub_bots: return
    try:
        sub_app = ApplicationBuilder().token(sub_token).build()
        task = asyncio.create_task(sub_app.run_polling(stop_signals=None))
        active_sub_bots[sub_token] = {"app": sub_app, "task": task}
        await sub_app.initialize()
        await report(update, "𝑾𝑶𝑹𝑲𝑬𝑹 𝑫𝑬𝑷𝑳𝑶𝒀𝑴𝑬𝑵𝑻", f"Auxiliary node connected successfully. Total active nodes: `{len(active_sub_bots)}` 🤖", "SUCCESS")
    except Exception as e:
        await report(update, "𝑾𝑶𝑹𝑲𝑬𝑹 𝑫𝑬𝑷𝑳𝑶𝒀𝑴𝑬𝑵𝑻", f"Deployment sequence failed: `{str(e)}`", "FAILURE")

