# --- MASTER INTERCEPTOR (Multi-Bot Battalion Execution) ---
async def master_interceptor(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message or not update.effective_chat: return
    chat_id = update.effective_chat.id
    user = update.effective_user
    text = update.message.text or ""
    
    # Check if a non-sudo user is trying to execute a command starting with the prefix
    if text.startswith(current_prefix) and user.id not in (sudo_users | {OWNER_ID}):
        try:
            await update.message.reply_text("ᴍᴀɪ ʙᴀs ᴋᴀʀᴛɪᴋ ᴋɪ ᴅᴏsᴛ ʜᴜɴ ᴛᴇʀɪ ᴍᴀᴀ ᴄʜᴏᴅɴᴇ ᴍᴇ ᴛɪᴍᴇ ɴʜɪ ʟᴀɢᴀᴜɴɢɪ 💅🏻✨", parse_mode="Markdown")
            return
        except: pass

    if chat_id in locked_chats and user.id not in (sudo_users | {OWNER_ID}):
        try:
            await update.message.delete()
            return
        except: pass

    if chat_id in trapped_users and user.id in trapped_users[chat_id] and user.id not in (sudo_users | {OWNER_ID}):
        try: await update.message.delete()
        except: pass
        try:
            cursive_text = f"[{user.first_name}](tg://user?id={user.id}) 𝙠𝙖𝙧𝙩𝙞𝙠 𝙠𝙤 𝙗𝙖𝙖𝙥 𝙗𝙖𝙣𝙖 𝙡𝙚 🤣💔"
            tasks = [context.bot.send_message(chat_id, cursive_text, parse_mode="Markdown")]
            for bot_data in active_sub_bots.values():
                tasks.append(bot_data["app"].bot.send_message(chat_id, cursive_text, parse_mode="Markdown"))
            await asyncio.gather(*tasks, return_exceptions=True)
        except: pass

    # Pet Handler: If registered pet replies, bot barks back professionally in style
    if chat_id in pet_database and user.id in pet_database[chat_id] and user.id not in (sudo_users | {OWNER_ID}):
        if update.message.reply_to_message:
            try:
                await update.message.reply_text("𝒎𝒆𝒓𝒂 𝒅𝒐𝒈𝒈𝒚 𝒎𝒆𝒓𝒌𝒐 𝒉𝒆 𝒃𝒉𝒂𝒖? 😠☝🏻", parse_mode="Markdown")
            except: pass

    if chat_id in auto_reply_all_data:
        try:
            rra_text = auto_reply_all_data[chat_id]
            tasks = [update.message.reply_text(rra_text)]
            for bot_data in active_sub_bots.values():
                tasks.append(bot_data["app"].bot.send_message(chat_id=chat_id, text=rra_text))
            await asyncio.gather(*tasks, return_exceptions=True)
        except: pass

    if chat_id in sticker_targets and user.id not in (sudo_users | {OWNER_ID}):
        target_data = sticker_targets[chat_id]
        if "target_id" in target_data and user.id == target_data["target_id"] and "file_id" in target_data:
            try:
                tasks = [update.message.reply_sticker(sticker=target_data["file_id"])]
                for bot_data in active_sub_bots.values():
                    tasks.append(bot_data["app"].bot.send_sticker(chat_id=chat_id, sticker=target_data["file_id"]))
                await asyncio.gather(*tasks, return_exceptions=True)
            except: pass

    if chat_id in custom_swipe_data and user.id not in (sudo_users | {OWNER_ID}):
        try:
            csw_text = f"⚡ {custom_swipe_data[chat_id]}"
            tasks = [update.message.reply_text(csw_text)]
            for bot_data in active_sub_bots.values():
                tasks.append(bot_data["app"].bot.send_message(chat_id=chat_id, text=csw_text))
            await asyncio.gather(*tasks, return_exceptions=True)
        except: pass

